import os
from typing import Optional, Dict, Any

import boto3
from botocore.exceptions import ClientError


class CognitoPasswordResetError(Exception):
    pass


def start_password_reset_flow(
    username: str,
    client_id: str,
    region_name: Optional[str] = None,
    client_metadata: Optional[Dict[str, str]] = None,
    secret_hash: Optional[str] = None,
    analytics_metadata: Optional[Dict[str, str]] = None,
    user_context_data: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    region = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    if not region:
        raise ValueError("AWS region is required via region_name, AWS_REGION, or AWS_DEFAULT_REGION")
    if not client_id:
        raise ValueError("client_id is required")
    if not username:
        raise ValueError("username is required")

    cognito = boto3.client("cognito-idp", region_name=region)

    params: Dict[str, Any] = {
        "ClientId": client_id,
        "Username": username,
    }

    if client_metadata:
        params["ClientMetadata"] = client_metadata
    if secret_hash:
        params["SecretHash"] = secret_hash
    if analytics_metadata:
        params["AnalyticsMetadata"] = analytics_metadata
    if user_context_data:
        params["UserContextData"] = user_context_data

    try:
        response = cognito.forgot_password(**params)
        return {
            "provider": "aws-cognito",
            "service": "cognito-idp",
            "delivery": response.get("CodeDeliveryDetails"),
            "status": "RESET_REQUESTED",
            "username": username,
        }
    except ClientError as e:
        error = e.response.get("Error", {})
        raise CognitoPasswordResetError(
            f"{error.get('Code', 'ClientError')}: {error.get('Message', 'Failed to start password reset flow')}"
        ) from e
